package setup

// initRouteRefusal asserts the refusal by its typed identity and exit, not by its sentence.
func initRouteRefusal(f *initFx) {
	f.t.Helper()
	f.wantError("provider", "login", 4)
}

package setup

import "strings"

func initRouteRefusal(f *initFx) {
	f.t.Helper()
	exit, _, _, err := f.run("")
	if exit != 4 || err == nil || !strings.Contains(err.Error(), "host/base URL and model") {
		f.t.Fatalf("exit %d error %v", exit, err)
	}
}

package setup

func initRouteRefusal(f *initFx) {
	f.t.Helper()
	exit, _, _, err := f.run("")
	if exit != 4 || err == nil {
		f.t.Fatalf("exit %d error %v", exit, err)
	}
}

package setup

import "github.com/KogenAI/kogen-loop/sys"

func initRouteRefusal(f *initFx) {
	f.t.Helper()
	_, _, _, err := f.run("")
	if e, ok := sys.AsError(err); !ok || e.Class != "provider" || e.Reason != "login" {
		f.t.Fatalf("error %v", err)
	}
}
